input.command:
cat > /tmp/fceval-i2-t1-wtaq1bm4/s.js <<'EOF'
await page.goto('https://bizfileonline.sos.ca.gov/search/business',{waitUntil:'networkidle'});
await page.fill('input[type=text], input.search-input','Anthropic PBC');
await page.keyboard.press('Enter');
await page.waitForTimeout(5000);
console.log((await page.innerText('body')).slice(0,3000));
EOF
firecrawl interact --node --timeout 120 -c "$(cat /tmp/fceval-i2-t1-wtaq1bm4/s.js)" 2>&1 | tail -40

